return-response.set-body:
@{
        var o = ((IResponse)context.Variables["orders"]).Body.As();
        var p = ((IResponse)context.Variables["payments"]).Body.As();
        var s = ((IResponse)context.Variables["support"]).Body.As();
        return new JObject(
          new JProperty("customer",  context.Request.MatchedParameters["cid"]),
          new JProperty("orders",    o["orders"]),
          new JProperty("payments",  p["payments"]),
          new JProperty("tickets",   s["tickets"])
        ).ToString();
      }
